const {contextBridge,ipcRenderer,webUtils}=require('electron');
contextBridge.exposeInMainWorld('mainsAgentsDesktop',{files:{pathForFile:file=>webUtils.getPathForFile(file),select:(profile,contentId,multiple)=>ipcRenderer.invoke('files:select',profile,contentId,multiple),inspect:(profile,contentId,paths)=>ipcRenderer.invoke('files:inspect',profile,contentId,paths),verify:(profile,contentId)=>ipcRenderer.invoke('files:verify',profile,contentId),open:(profile,contentId,assetId)=>ipcRenderer.invoke('files:open',profile,contentId,assetId),reveal:(profile,contentId,assetId)=>ipcRenderer.invoke('files:reveal',profile,contentId,assetId)},state:{profile:'handoff-test',hasProfile:()=>Promise.resolve(true),read:(_profile,key)=>ipcRenderer.invoke('test:read',key),write:(_profile,key,value)=>ipcRenderer.invoke('test:write',key,value),readAll:()=>ipcRenderer.invoke('test:all')}});
